\label{convex}
Let $f\colon\mathbb R\to\mathbb R$. 
Then, the convex envelope of $f$ is 
\begin{eqnarray*}
&&f^{\ast\ast}(z)=\displaystyle\lim_{k\to+\infty}\frac{1}{k}\inf\bigg\{\sum_{i=1}^k f(u(i)-u(i-1)): \ 
u \in \mathcal A(k; z)
\bigg\}.
\end{eqnarray*}

\label{propT} 
Let $\bf m$ be as in \eqref{propm} and let $f\colon \mathbb R\to [0,+\infty)$ be a non-negative 
function satisfying \eqref{crescita} and \eqref{crescitasotto}. Then the function $\widehat Q_{\bf m}f$ is convex.

\label{ubquic} 
Let $m_1>0$, so that \eqref{crescitasotto} is satisfied with $f=0$. 
Then we have $\widehat Q_{\bf m}0(z)= a_{\bf m}z^2$.

\label{gecoin}\rm In the previous proposition we have considered quadratic interactions between $M$th neighbours. Actually, it is not necessary to assume quadraticity or even convexity of these interactions, and the same proof shows that
\begin{equation}
\lim_{k\to+\infty}{1\over k}\min\Bigl\{\sum_{i=1}^kf(u_i-u_{i-1})+ \sum_{i=M}^kg(u_i-u_{i-M}): u_0=0, u_k=kz\Bigr\}=  \psi^{**}(z),
\end{equation}
where $f,g\colon\mathbf R\to[0,+\infty)$ are such that
 $f$ is of quadratic growth and $g$ satisfies a quadratic bound from above, and  $\psi$ is defined by
\begin{equation}\label{lowerPM-gen}
\psi(z)=\frac{1}{M}\min\bigg\{\sum_{j=1}^Mf(z_j): \sum_{j=1}^{M}z_j=Mz\bigg\}+g(z).
\end{equation}

\label{defin} 
Let $\bf m$ be as in \eqref{propm} and let $f\colon\mathbb R\to[0,+\infty)$ satisfy \eqref{crescita} and \eqref{crescitasotto}.  
The {\em ${\mathbf m}$-transform of $f$}  is the function $Q_{\bf m}f\colon\mathbb R\to[0,+\infty)$ defined as 
\begin{equation}\label{quet}
Q_{\bf m}f(z)=\widehat Q_{\bf m}f(z)-a_{\mathbf m}z^2.
\end{equation}

\label{comst}\ 

{\rm \ (i)} if $f$ is $\bf m$-stable then $f_{a_{\bf m}}$ is convex;

{\rm (ii)} if $f_{2m_1}$  is convex then $f$ is $\bf m$-stable.

\label{nocopeco}\rm
The proposition above implies that if $f$ is  `moderately non-convex' then it is also $\bf m$-stable.  This is valid in particular if $f$ is twice differentiable and  \begin{equation}\label{modnconv}
\inf_z f^{\prime\prime}(z)>-4 m_1.
\end{equation}

\label{stab1M}
Let $\bf m$ be a non-trivial kernel concentrated at $M\geq 2$; that is,  with $m_M\neq 0$.  
In this case: 

{\rm \ \ (i)} $f$ is ${\bf m}$-stable if and only if $f_{2m_1}$ is convex; 

{\rm \ (ii)}  if $f_{2m_1}$ is not convex then for any $n$, there exists $z$ such that 
$Q_{\bf m}^nf(z)>Q_{\bf m}^{n+1}f(z)$; 

{\rm (iii)}  $Q_{\bf m}^{\infty}f(z)=f_{2m_1}^{\ast\ast}(z)-2m_1z^2$.

\label{cormult}
The same claims of the previous proposition hold if $\bf m$ is such that $M\geq 2$ exists such that 
$m_n=0$ if $n\not\in\{1, M\mathbb N\}$.

\label{interpolation-sigma} 
Let $m\colon[0,+\infty)\to[0,+\infty)$ be as above, and for all $\sigma>0$ consider the kernel  ${\bf m}^\sigma=\{m(\sigma n)\}_n$. Let $f\colon \mathbb R\to [0,+\infty)$ satisfy growth assumptions \eqref{crescita} and $\eqref{crescitasotto}$.  
Then,   
\begin{equation}\label{interpsigma}
\lim_{\sigma\to+\infty}
Q_{{\bf m}^\sigma} f(z)=f^{\ast\ast}(z) \ \ \hbox{\rm and }\ \ 
\lim_{\sigma\to 0^+} Q_{{\bf m}^\sigma} f(z)= \overline f(z).
\end{equation}

\label{const_min}\rm
To understand the role of the constrained minimization producing the function $\widehat Q_{\bf m}f(\theta,z)$ and to reveal the link between the shape of the phase function $\theta(z)$ and  the structure of the  relaxed energy  $\widehat Q_{\bf m}f$, it will be instructive  to consider first the case when 
only $M$-neighbour interactions are taken into account. We recall that in this case  there exists $M\geq 2$ such that $m_M\neq 0$ and $m_n=0$ for any $n\neq M$. 

Proposition \ref{MniPM} gives a formula for $\widehat Q_{\bf m}f(z)$. 
If $f$ is bi-convex, we can subdivide its computation 
by introducing  a dependence on  the fraction $\theta$ of $z_i=u_i-u_{i-1}$ belonging to the convexity region $A$. 
More precisely, for any $n=0,\dots, M$ we can first compute the minimum at  a fixed fraction 
$\theta_n=\frac{n}{M}$ of $z_i$ belonging to $A$.  Using the convexity, 
such  minimum problems reduce to the computation of   
\begin{equation}\label{pieMMeenne}
\left. \begin{array}{ll}
P^{M,n}(z)=&\displaystyle\min\Big\{(1-\theta_n)f(z^-)+\theta_n f(z^+): z^-\leq z^\ast, z^+\geq z^\ast, \\
&\hspace{2cm}\displaystyle(1-\theta_n)z^-+\theta_nz^+=z\Big\}
+2m_M(Mz)^2. 
\end{array}
\right. 
\end{equation} 
The optimal bounds are then completely characterized by the functions $P^{M,n}$, in the sense that 
\begin{equation*}
\widehat Q_{\bf m}f(z)=\big(\min_n P^{M,n}(z)\big)^{\ast\ast}.
\end{equation*}  
We will show that all the $M+1$ values $\theta_n$ are locking states in the sense above. These values of $\theta$ are particularly relevant since the shape of $\widehat Q_{\bf m}f(z)$ will be shown to depend exclusively on `phase mixtures' with `volume fraction' $\theta_n$. Another property enjoyed by $\theta_n$ is that the minimum problems corresponding to values of $z$ for which $\theta(z)=\theta_n$ admit periodic solutions.

\label{minpro}
The following equality holds:
$$\inf_{\theta\in\mathbb Q\cap[0,1]}\widehat Q_{\bf m}f(\theta,z)=\widehat Q_{\bf m}f(z).$$

\label{boundary-Q}  
The following equality holds 
\begin{eqnarray*} 
\widehat Q_{\bf m}f(\theta,z)=\lim_{\delta\to 0}
\liminf_{k\to+\infty}\frac{1}{kq}\inf\Big\{F_1(u;[0,kq]): u\in \mathcal V(kq;\theta) \cap \widetilde{\mathcal A}_\delta(kq;z)  
 \Big\} \nonumber
\end{eqnarray*}
for any $\theta=\frac{p}{q}\in \mathbb Q\cap[0,1]$ and $z\in\mathbb R$.

\label{dwm0}\rm 
For any $t>1$ we define 
$$f^{t}(z)=\begin{cases}
z^2 & \hbox{\rm if }\ z\leq 1 \\
\displaystyle\Big(\frac{z-{t}}{1-{t}}\Big)^2 & \hbox{\rm if }\ z\geq 1.
\end{cases}$$
If $\theta\in(0,1)$, we get 
$$Q_{\bf 0}f^{t}(\theta,z)=\begin{cases}
\vspace{2mm}
\displaystyle\frac{(z-\theta)^2}{1-\theta}+\theta & \displaystyle\hbox{\rm if }\ z\leq \frac{1-\theta {t}}{1-{z_0}}\\
\vspace{2mm}
\displaystyle\frac{(z-\theta {t})^2}{1-\theta+\theta(1-{t})^2} & \displaystyle\hbox{\rm if }\ \frac{1-\theta {t}}{1-{t}}\leq z\leq 
1+\theta {t}({t}-1)\\
\displaystyle\frac{(z-1+\theta(1-{t}))^2}{\theta(1-{t})^2}+1-\theta 
& \displaystyle\hbox{\rm if }\ z\geq 
1+\theta {t}({t}-1) 
\end{cases}$$
(see Fig.~\ref{fig_fb1} and Fig.~\ref{fig_fb2} for the graph of $Q_{\bf 0}f^{t}(\theta,z)$ and $\theta(z)$, respectively, with different values of 
$\theta$ and ${t}$ fixed). 
\begin{figure}[h!]
\centerline{\includegraphics[width=1\textwidth]{FIGURE_fb3}}
\caption{Graph of $Q_{\bf 0}f^{t}(\theta,z)$ with $\theta$ fixed and increasing values of ${t}$.}
\label{fig_fb3}
\end{figure} 

In Fig.~\ref{fig_fb3} we picture the graph for a fixed $\theta$ and increasing values of ${t}$.

\label{tcm0}\rm 
\begin{figure}[h!]
\centerline{\includegraphics[width=1\textwidth]{FIGURE_frattura_0}}
\caption{(a) $Q_{\bf 0}f(\theta,z)$ for a truncated convex potential and (b) $\theta\mapsto Q_{\bf 0}f(\theta,z)$ for different values of $z$.}
\label{fig_frattura_0}
\end{figure} 
Let $f$ be the truncated convex given by  
\begin{equation}\label{def-ftrunc1}
f(z)=\begin{cases} \tilde f(z) & \hbox{\rm if } z\leq z^\ast\\
\tilde f(z^\ast) 
& \hbox{\rm if } z\geq z^\ast, 
\end{cases}
\end{equation}
where $\tilde f$ is a convex function such that 
the only minimum point of $\tilde f$ is $0$ with $\tilde f(0)=0$, and $z^\ast>0$. 
In particular, we can take $\tilde f(z)=z^2$, in which case $f$ is called a truncated quadratic potential. 
For $\theta\in(0,1)$ we get 
\begin{eqnarray*}
&&Q_{\bf 0}f(\theta,z)=\begin{cases}
\vspace{1mm}
\displaystyle\theta f(z^\ast)+(1-\theta)
f\Big(\frac{z-\theta z^\ast}{1-\theta}\Big) & \hbox{ if } z <  \theta z^\ast\\
\displaystyle\theta f(z^\ast)  & \hbox{ if } z \geq \theta z^\ast. 
\end{cases} 
\end{eqnarray*} 
For all such $f$ the graphs of $Q_{\bf 0}f(\theta,z)$ and of $Q_{\bf 0}f(z)$ have the form as those pictured in Fig.~\ref{fig_frattura_0}(a). 
In Fig.~\ref{fig_frattura_0}(b) the function $\theta\mapsto Q_{\bf 0}f(\theta,z)$ is represented for two different values of $z$, highlighting the lack of lower semicontinuity in $0$ if $z>0$.   
Note that for any $\theta\in(0,1)$ we have $Q_{\bf 0}f(\theta,z)> 
f(z)$ in $(-\infty,\theta z^\ast]$.  
Moreover, 
the optimal volume fraction $\theta(z)$ is always equal to zero, 
even though $Q_{\bf 0}f(\theta,z)=Q_{\bf 0}f(0,z)$ only if $z\leq 0$ 
(see Remark \ref{lockingrem} below).

For $\theta\in(0,1)$, we have  
	\begin{equation}\label{qtetaconvessa}
	Q_{\bf m}f(\theta,z)=
	\begin{cases}\vspace{1mm}
	\displaystyle \theta f(z^\ast)+(1-\theta)f\Big(\frac{z-\theta z^\ast}{1-\theta}\Big) 
	+a_{\bf m}\frac{\theta}{1-\theta}(z-z^\ast)^2
	& {\rm if }\ z<z^\ast \\
	\displaystyle (1-\theta) f(z^\ast)+\theta f\Big(\frac{z-(1-\theta) z^\ast}{\theta}\Big) 
	+a_{\bf m}\frac{1-\theta}{\theta}(z-z^\ast)^2
	& {\rm if }\ z\geq z^\ast. 
		\end{cases}
	\end{equation}

\label{plasticity-ex2}\rm 
	\begin{figure}[h!]
		\centerline{\includegraphics[width=0.9\textwidth]{FIGURE_convexaffinege1}}
		\caption{$Q_{\bf m}
		\ell^\tau(\theta,z)$ for increasing values of $\theta$.}
		\label{figure_convexaffinege1}
	\end{figure} 
	Let  
	$\ell^\tau$ 
	be defined as in \eqref{quadraticalfa}. In the convex case $\tau\geq 1$, for any $\theta\in(0,1)$ we have  
	\begin{equation*}
	Q_{\bf m}
	\ell^\tau(\theta,z)=\begin{cases}
	\vspace{2mm}
	\displaystyle\frac{1+a_{\bf m}\theta}{1-\theta}z^2
	-\frac{2(1+a_{\bf m})\theta}{1-\theta}z
	+\frac{(1+a_{\bf m})\theta}{1-\theta}&\hbox{\rm if } z\leq1\\
	\displaystyle\frac{a_{\bf m}(1-\theta)}{\theta} z^2
	-\Big(\frac{2a_{\bf m}(1-\theta)} {\theta} -\tau\Big)z+
	1-2\tau+\frac{a_{\bf m}(1-\theta)}{\theta}  
	&\hbox{\rm if } z\geq1
	\end{cases}
	\end{equation*}
\noindent These constructions are illustrated in Fig.~\ref{figure_convexaffinege1}.

\label{energiuel} Let $f$ be as in \eqref{fmin} and let $\Phi^N_{\bf m}$ be as in \eqref{deffin}. The value $\theta\in [0,1]\cap\mathbb Q$ 
is an {\rm energy   well of $f$  at $z$} (related to the sequence ${\bf m}$) if there exists $N$ such that $N\theta\in\mathbb Z$ and
\begin{equation}\label{enwelldef}
\Phi^N_{\bf m} f(\theta,z)=\Phi_{\bf m} f(\theta,z).
\end{equation}
We say 
that $\theta$ is an {\rm energy well of $f$ in an open interval $I$} 
if there exists $N$ such that \eqref{enwelldef} holds for all $z\in I$; 
if such $I$ exists, we say that $\theta$ is a {\em non-degenerate energy well of $f$}. 
If $I=\mathbb R$, we simply say that 
$\theta$ is an {\rm energy well of $f$}.

Let $X\subset[0,1]\cap \mathbb Q$ be such that 
\begin{equation}\label{inftheta}
\Big(\inf_{\theta\in X}\{\widehat Q_{\bf m}f(\theta,z)\}\Big)^{\ast\ast}
= \widehat Q_{\bf m}f(z)
\end{equation} 
for all $z$, and let $\theta^\ast\in X$ be an energy well that is {\em essential} in \eqref{inftheta}; that is, such that
\begin{equation}\label{minimality}
\Big(\inf_{\theta\in X\setminus\{\theta^\ast\}}\{\widehat Q_{\bf m}f(\theta,z)\}\Big)^{\ast\ast}
> \widehat Q_{\bf m}f(z)
\end{equation} 
 for some $z$. Then, $\theta^\ast$ is a locking state.

\label{rem-shapeM}\rm  Note that if $\theta(z)=\theta_n$ then the value of $\widehat Q_{\bf m}f(z)$ is attained on periodic minimizers. 
The phase function $\theta$ 
can be explicitly written as 
\begin{equation}\label{tetaM}
\theta(z)=\begin{cases}\vspace{2mm}
0 & \hbox{\rm if } \ z\leq s_0^+\\
\displaystyle\theta_n+\frac{1}{M}\frac{z-s_n^+}{s_{n+1}^--s_n^+} &  \hbox{\rm if } \ s_n^+ \leq z \leq s_{n+1}^-\\
\displaystyle\theta_n & \hbox{\rm if } \ s_n^- \leq z \leq s_{n}^+\\
 1 & \hbox{\rm if } \ s_M^- \leq z.  
\end{cases}
\end{equation} 
Moreover, if we write the convex envelope of the minimum of $P^{M,n}$ and $P^{M,n+1}$  
as 
\begin{equation}\label{minpnm} 
\min\big\{P^{M,n},P^{M,n+1}\big\}^{\ast\ast}(z)=\begin{cases}
P^{M,n}(z) &  \hbox{\rm if } \ z \leq s_{n}^+\\
r^{M,n}(z) &  \hbox{\rm if } \ s_n^+ \leq z \leq s_{n+1}^-\\
P^{M,n+1}(z) &  \hbox{\rm if } \  s_{n+1}^-\leq z, 
\end{cases}
\end{equation} 

where $r^{M,n}$ is the interpolating affine function 
\begin{eqnarray*}
r^{M,n}(z)&=&P^{M,n}(s_n^+)+\frac{P^{M,n+1}(s_{n+1}^-)-P^{M,n}(s_n^+)}{s_{n+1}^--s_n^+}(z-s_n^+),
\end{eqnarray*}   
then $\widehat Q_{\bf m}f(z)=r^{M,n}(z)$ if $z\in[s_n^+,s_{n+1}^-]$.   
Note that this characterization of $\widehat Q_{\bf m}f$ holds under assumption \eqref{crescitasotto}, while it may fail if this condition is dropped, as we show in Remark \ref{casem10} below.

\label{alphaklemma} 
Let $n\in[0,M-1]\cap \mathbb N$.  If $\theta\in \big[\frac{n}{M},\frac{n+1}{M}\big]$, then there exist coefficients  $\alpha^n_k$, $k=0,\dots, M$, such that $\alpha^n_k\in [0,I_k]$ for any $k$ 
and 
\begin{equation}\label{alphak}
\begin{cases}
\displaystyle\sum_{k=0}^M\alpha^n_k=\frac{M\theta-n}{M}Nq\\
\displaystyle\sum_{k=0}^Mk\alpha^n_k=(n+1)\frac{M\theta-n}{M}Nq. 
\end{cases}
\end{equation}

\label{formula-n-prop}
Let $\theta\in[\theta_n,\theta_{n+1}]\cap \mathbb Q$, 
with $n$ integer such that $0\leq n<M$, and $\theta_n=\frac{n}{M}$ as above.  
Then the following formula holds: 
\begin{eqnarray}\label{formula-n}\nonumber
&&\widehat Q_{\bf m}f(\theta,z)=\displaystyle\min\Big\{M(\theta_{n+1}-\theta) P^{M,n}(w_n)
+M(\theta-\theta_n) P^{M,n+1}(w_{n+1}): \\
&& \hspace{3cm}
M(\theta_{n+1}-\theta)w_n+M(\theta-\theta_n)w_{n+1}
= z\Big\}. 
\end{eqnarray}

\label{casem10dw}\rm 
\begin{figure}[h!]
\centerline{\includegraphics[width=0.5\textwidth]{FIGURE_lim-m10}}
\caption{the limit of $Q_{{\bf m}^\sigma}f$ for $\sigma\to0$ in the case $m_1=0$.}
\label{lim-m10}
\end{figure} 

If $m_1=0$, Remark \ref{sigmasing} does not apply. 
Taking the limit for $\sigma\to 0^+$, in this case we obtain 
\begin{equation}\label{tnsndwsigma0}
\lim_{\sigma\to 0^+}s_n^+(m_1^\sigma, m_M^\sigma)=z_n, 
\ \ \ \hbox{\rm and }\ \ \ 
\lim_{\sigma\to 0^+}s_n^-(m_1^\sigma, m_M^\sigma)=z_{n-1}, 
\end{equation} 
where we set 
$$z_n=\frac{2n+1-M}{M}.$$
The limit function is then given by  
$$\lim_{\sigma\to 0^+}Q_{{\bf m}^\sigma}f(z)=
\begin{cases}
(1+z)^2& \displaystyle \hbox{\rm if } \ z\leq z_0\\
\displaystyle \big(z+(1-2\theta_n)\big)^2
& \displaystyle\hbox{\rm if } \ 
z_{n-1}\leq z \leq z_{n}\\
 (1-z)^2 & \displaystyle \hbox{\rm if } \ z_M\leq z, 
\end{cases}
$$
or, equivalently, 
\begin{equation*}
\lim_{\sigma\to 0^+}Q_{{\bf m}^\sigma}f(z)=\min_{0\leq n\leq M}
\big\{ \big(z+(1-2\theta_n)\big)^2\big\}
 =\min_{0\leq n\leq M}\{Q_{\bf m}f(\theta_n,z)\}. 
\end{equation*} 

\begin{figure}[h!]
\centerline{\includegraphics[width=.9\textwidth]{FIGURE_Grafico1-4m_1=0}}
\caption{Representation of $\theta$ in the $z$-${1\over\sigma}$ plane for $M=4$ (case $m_1=0$)}
\label{tongue-M10}
\end{figure} 
Note that in this case the limit differs from $f$ but coincides with the minimum among $P^{M,n}(z)-2m_M M^2 z^2$ (see Fig.~\ref{lim-m10}), whose convexification still equals $f^{**}$. 

In Fig.~\ref{tongue-M10} we picture in the $z$-${1\over\sigma}$-plane the zones where $\theta(z)=\theta_n$ for some $n\in\{0,\ldots, M\}$ and those where $\theta(z)$ is affine for fixed $\sigma$ (in grey).

\label{teo-equivalence}
Let ${\bf m}$ satisfy \eqref{propm} and be such that 
the function $n\mapsto m_n$ is not increasing for $n$ large enough.
Then, there exist a $(k+1)\times (k+1)$-dimensional matrix $A^k_{\bf m}$ and a scalar $s_{\bf m}$ such that, setting 
$H^k_{\bf m}=H^k[A^k_{\bf m}, s_{\bf m}]$ in \eqref{defjkm1},
the following equality holds 
\begin{equation}\label{equiv-2v}
\widehat Q_{\bf m}f(z)=\lim_{k\to+\infty}\frac{1}{k}\min\Big\{\sum_{i=1}^kf(u_i-u_{i-1})+
H^k_{\bf m}(u,v): u,v\in
\mathcal A(k,z)\Big\} 
\end{equation}
for all $f\colon\mathbb R\to [0,+\infty)$ satisfying  growth conditions \eqref{crescita} and \eqref{crescitasotto}.

\label{2v-lemma}
Let ${\bf m}$ satisfy \eqref{propm} and be such that the function 
$n\mapsto m_n$ is not increasing for $n$ large enough. Let $J_{\bf m}^k$ be as in \eqref{defjkm}. 
Then, there exist a $(k+1)\times (k+1)$-dimensional matrix $A^k_{\bf m}$ and a scalar $s_{\bf m}$ such that 
\begin{equation}\label{minG}
\min\{H^k_{\bf m}(u,v): v\colon\{0,\dots,k\}\to\mathbb R\}=J_{\bf m}^k(u)+\|u\|_k^2\ o\Big(\frac{1}{k}\Big) 
\end{equation}
for all $u\colon\{0,\dots, k\}\to\mathbb R$, where $H_{\bf m}^k$ is defined in Theorem \ref{teo-equivalence}.

\label{lobaloba}
We have
\begin{equation}\label{lobbi}
\lim_{k\to+\infty}{1\over k}\min\Bigr\{E(u,v; [0,k]): u_k-u_0=v_k-v_0=kz\Bigl\} \ge \Bigl(\inf_N g_N(z)\Bigr)^{**}.
\end{equation}

\label{teo-equivalence-exp}
Let 
\begin{equation}\label{aeb}
a_\sigma=a_{{\bf m}^\sigma}=\frac{2(1+e^{-\sigma}) e^{-\sigma}}{(1-e^{-\sigma})^3}, \quad \quad 
b_\sigma=
\frac{2(1+e^{-\sigma})}{(1-e^{-\sigma})}, 
\end{equation} 
and set $E^\sigma_\varepsilon=E_\varepsilon$ as defined in \eqref{def-2var} with $a=a_\sigma$ and $b=b_\sigma$. 
Then the sequence $E^\sigma_\varepsilon$ $\Gamma$-converges  to the same $\Gamma$-limit as the sequence $F^\sigma_\varepsilon$.

\label{absigma}\rm 
The equivalence result in Theorem \ref{teo-equivalence-exp} can be extended to arbitrary pairs $a,b>0$ up to considering 
the non-local functionals with kernel $m_n=\varrho e^{-\sigma n}$; that is, the functionals given by 
$$
F^{\varrho,\sigma}_\varepsilon(u;I)=\varepsilon\sum_{i,i-1\in \mathcal I_\varepsilon(I)}f\Big(\frac{u_i-u_{i-1}}{\varepsilon}\Big)+
\varepsilon \, \varrho\sum_{i,j\in \mathcal I_\varepsilon(I)}e^{-\sigma |i-j|}
\Big(\frac{u_i-u_j}{\varepsilon}\Big)^2, 
$$
with the choices 
\begin{equation}\label{absigmarho}
\sigma=\sigma_{a,b}=2\sinh^{-1}\Big(\frac{1}{2}\sqrt{\frac{b}{a}}\Big) \quad \hbox{ and } \quad \varrho=\varrho_{a,b}=\frac{b^2}{4a\sinh(\sigma_{a,b})}.
\end{equation}
Indeed, with this definition we get 
\begin{eqnarray*}
\frac{a}{\varrho_{a,b}}=\frac{2(1+e^{-\sigma_{a,b}})e^{-\sigma_{a,b}}}{(1-e^{-\sigma_{a,b}})^3}
=a_\sigma
\ \ \hbox{ and }\ \ \frac{b}{\varrho_{a,b}}=\frac{2(1+e^{-\sigma_{a,b}})}{1-e^{-\sigma_{a,b}}}
=b_\sigma, 
\end{eqnarray*}
so that we can apply Theorem \ref{teo-equivalence-exp} obtaining the equivalence between $\frac{1}{\varrho}F_\varepsilon^{\varrho,\sigma}$ and $\frac{1}{\varrho}E^{\sigma}_\varepsilon$.  
The corresponding (trivial) generalization of  $Q_\sigma f$ in \eqref{def-tsigma} 
can be obtained by defining
\begin{equation}\label{def-tsigmar} 
\widehat Q_{\sigma,\varrho} f(z)=\!\lim_{k\to+\infty}\frac{1}{k}\inf\Big\{\sum_{i=1}^k f(u_i-u_{i-1})+
\varrho\sum_{i,j=0}^k e^{-|i-j|\sigma}(u_i-u_j)^2: 
 u \in \mathcal A(k; z)\Big\}, 
 \end{equation} \
and setting $Q_{\sigma,\varrho} f(z)=\widehat Q_{\sigma,\varrho} f(z)-a_\sigma \varrho z^2$, with $a_\sigma$ as in \eqref{aeb}.

\label{lemma-equivalence} 
Let $L>0$ and $k_\varepsilon=\lfloor\frac{L}{\varepsilon}\rfloor$. We fix $\alpha\in(0,1)$ and set $n_\varepsilon=\lfloor (k_\varepsilon)^\alpha \rfloor$.
Let $F^\sigma_\varepsilon$ be given by \eqref{def-fe-sigma} and $E^\sigma_\varepsilon$ be given by \eqref{def-2var} 
with $a_\sigma,b_\sigma$ as in \eqref{aeb} and $I=[0,L]$.
Then, if $u^\varepsilon\in\mathcal A_\varepsilon=\mathcal A_\varepsilon([0,L])$ satisfies $u^\varepsilon_i=u^\varepsilon_0$ for $i\leq n_\varepsilon$, $u^\varepsilon_i=u^\varepsilon_{k_\varepsilon}$ for $i\geq k_\varepsilon-n_\varepsilon$, we have
\begin{equation}\label{formula-lemma}
\min\{E^\sigma_\varepsilon(u^\varepsilon,v;[0,L])\!:  v\in 
\mathcal A_\varepsilon^{\#}(u^\varepsilon)\}=F^\sigma_\varepsilon(u^\varepsilon; [0,L])+\|u^\varepsilon\|^2_{L^2}\ o(1)_{\varepsilon\to 0}
\end{equation}
where $\mathcal A_\varepsilon^{\#}(u^\varepsilon)=\{v\in 
\mathcal A_\varepsilon: v_0=v_1=u^\varepsilon_0, \ v_{k_\varepsilon}=v_{k_\varepsilon-1}=u^\varepsilon_{k_\varepsilon}\}$.

\label{localQ}\rm
Formula \eqref{equiv-2v} in Theorem \ref{teo-equivalence} 
and equality \eqref{hh} prove the following formula for the function $\widehat Q_{\sigma}f$ defined in \eqref{def-tsigmahat}:  
\begin{equation}\label{trs}
