\label{convinN}
The functions $g_N$ are uniformly strictly convex. More precisely, we have
 \begin{equation}\label{unifconv}
 {1\over2} g_N(z)+{1\over2} g_N(z')\ge g_N\Bigl({z+z'\over 2}\Bigr)+a\Bigl({z-z'\over 2}\Bigr)^2
 \end{equation}
 for all $z,z'\in\mathbb R$ and $N\in\mathbb N$.

\label{gnprop}\rm
The solutions $u,v$ of the minimum problem
\begin{equation}\label{pro-si}
\min\bigg\{\sum_{i=2}^N\tilde f ({u_i-u_{i-1}} )+
a\sum_{i=2}^N(v_i-v_{i-1})^2
+b\sum_{i=1}^N(u_i-v_i)^2
: v_1=v^1, v_N=v^N\bigg\}
\end{equation}
are symmetric with respect to the centre of the interval, in the sense that
\begin{equation}\label{symm-1}
v_{j+1}-v_j= v_{N-j+1}- v_{N-j}, \qquad u_{j+1}-u_j= u_{N-j+1}- u_{N-j}
\end{equation}
for $1\le j\le N-1$. Furthermore, if $N=2M+1$ is odd then
\begin{equation}\label{symm-2}
v_{M+1}=u_{M+1}= {v^N+v^1\over 2}
\end{equation}
while, if $N=2M$ is even then 
\begin{equation}\label{symm-3}
{v_{M+1}+v_{M}\over 2}={u_{M+1}+u_{M}\over 2}= {v^N+v^1\over 2}.
\end{equation}

Indeed, first note that we may state the boundary condition equivalently as $v_N-v_1= V:=v^N-v^1$.
Then, condition \eqref{symm-1} is a direct consequence of the strict convexity of the energy and is obtained using
\begin{equation}\label{symm-4}
\overline v_i= {v_i-v_{N+1-i}\over 2},\qquad \overline u_i= {u_i-u_{N+1-i}\over 2}
\end{equation}
as test functions. 
To check, e.g., \eqref{symm-2}, note that from \eqref{symm-1}
\begin{eqnarray*}
v_{M+1}&= &v_1+\sum_{j=1}^{M}(v_{j+1}-v_j)=v_1+\sum_{j=1}^{M}(v_{N-j+1}- v_{N-j})\\
&=&v_1+\sum_{k=M+1}^{N-1}(v_{k+1}- v_{k}) = v_N-v_{M+1}+v_1,
\end{eqnarray*}
from which the first equality in \eqref{symm-2} follows. 
To check the second one, note that from \eqref{symm-1} we obtain 
$v_i+v_{2M+2-i}-2v_{M+1}=u_i+u_{2M+2-i}-2u_{M+1}=0$ for all $i$,
from which 
\begin{equation}\label{symm-5}
{1\over N}\sum_{i=1}^Nu_i= u_{M+1},\qquad {1\over N}\sum_{i=1}^Nv_i= v_{M+1}.
\end{equation}
Now, considering in place of $u_i$ the function
$$
\overline u_i= u_i+{v^1+v^N\over 2}-u_{M+1},
$$
as test functions, the only change in the problem in \eqref{pro-si} is in the last sum,
for which, using \eqref{symm-5} and the already proved equality in \eqref{symm-2} for $v$, we have
\begin{eqnarray*}
\sum_{i=1}^N(\overline u_i-v_i)^2=
 \sum_{i=1}^N(u_i-v_i)^2-N\Bigl({v^1+v^N\over 2}-u_{M+1}\Bigr)^2,
\end{eqnarray*}
which contradicts the minimality of $u,v$ if the second equality in \eqref{symm-2} does not hold.
The proof of \eqref{symm-3} follows the same line with minor modifications.

\label{gin1n2}
