\label{BCS-remark}\rm 
The $\Gamma$-limit of $G_\varepsilon$ with respect to the convergence $u_\varepsilon,v_\varepsilon\to v$ in $L^2(I)$ is given by 
$$G_{\rm hom}(v)=\int_I g_{\rm hom}(v^\prime)\, dt.$$ 
The integrand $g_{\rm hom}$ is characterized as 
\begin{equation}\label{def-gchom}
g_{\rm hom}(z)=\inf_{S>0} \Big\{\lambda_S z^2+\frac{\eta}{S}\Big\}
\end{equation}
where 
\begin{equation}\label{def-lambda}
\lambda_S=\frac{(\alpha+\gamma)\frac{\omega S}{2}}{\frac{\omega S}{2}+\frac{\gamma}{\alpha} \tanh(\frac{\omega S}{2})} \quad \hbox{ and } \quad \omega^2=\frac{(\alpha+\gamma)\beta}{\alpha\gamma}. 
\end{equation}
The function $g_{\rm hom}(z)$ is strictly convex, and the following properties hold: 
\smallskip 

{\rm (i)} $\displaystyle g_{\rm hom}(z)=(\alpha+\gamma) z^2$  in $ [0,z_c]$, 
where $z_c=\sqrt \frac{2\eta\omega \alpha}{4\gamma(\alpha+\gamma)}$;

\smallskip 

{\rm (ii)} 
$\displaystyle g_{\rm hom}(z)\sim 
\alpha z^2 +Cz^{2/3}$ as $z\to+\infty$,
where $C>0$ depends only on $\alpha,\beta, \gamma,\eta$.

\label{salti-interi}
The sequence $G^{\mathbb Z}_\varepsilon(u,v;I)$ $\Gamma$-converges with respect to the convergence 
$u_\varepsilon,v_\varepsilon\to v$ in $L^2(I)$ to 
\begin{equation}
G^{\mathbb Z}_{\rm hom}(v)=\int_I g^{\mathbb Z}_{\rm hom}(v^\prime)\, dt
\end{equation}
where 
\begin{equation}\label{def-echom} 
g^{\mathbb Z}_{\rm hom}(z)=
\displaystyle\lim_{N\to+\infty}
\frac{1}{N}\inf\{G_1^{\mathbb Z}(u,v; (0,N))\!: \ \! u(0)=v(0)=0, \ \! u(N)=v(N)=Nz\}.
\end{equation}

For any $z\in\mathbb R$ the following equality holds: 
\begin{equation}\label{uguali-discreto}
g^{\mathbb Z}_{\rm hom}(z)=\Big(\inf_{N\in\mathbb N}\Big\{\lambda_N z^2+\frac{\eta}{N}\Big\}\Big)^{\ast\ast}.
\end{equation}

We fix $z\in\mathbb R$ and $N\in\mathbb N$; let $(u_N, v_N)$ be the solution of the minimum problem defining $\psi(N,z)$. 
We define $\tilde u_N\in SBV(0,2N)$ by setting 
\begin{equation}\label{estensione}
\tilde u_N(t)=\left\{ 
\begin{array}{ll} 
2u_N(\frac{t+N}{2})-Nz & \hbox{ if } \ t\in(0,N)\\
2u_N(\frac{t-N}{2})+Nz & \hbox{ if } \ t\in(N,2N)
\end{array}
\right.  
\end{equation}
and correspondingly $\tilde v_N\in H^1(0,2N)$. Since $u_N(\frac{N}{2})=v_N(\frac{N}{2})=\frac{N}{2}z$, 
then $S(\tilde u_N)=\{N\}$, $\tilde u_N(0)=\tilde v_N(0)=0$ and $\tilde u_N(2N)=\tilde v_N(2N)=2Nz$; by construction 
$$\frac{1}{2N} \tilde G_1(\tilde u_N,\tilde v_N;(0,2N))=
\frac{1}{N}\tilde G_1(u_N,v_N;(0,N))=\displaystyle
\lambda_N z^2.$$ 
Let $k\in\mathbb N$. We define $\tilde u$ in $(0,2kN)$ by setting  
\begin{equation*}
\tilde u(t)=
 \tilde u_N(t-2jN)+2jNz \quad \hbox{ in } \quad (2jN, 2(j+1)N), \ \ \  j=0,\dots, k-1 
\end{equation*}
and in the same way we define $\tilde v$. 
By construction, $S(\tilde u)\subset \mathbb N$ and $\# S(\tilde u)=k-1$; hence, 
since the boundary conditions for $\tilde u$ and $\tilde v$ hold, we have
\begin{eqnarray*} 
\displaystyle
\lambda_N z^2+\frac{\eta}{N}&=&
\frac{1}{2kN} \tilde G_1(\tilde u,\tilde v;(0,2kN))+\frac{\eta (k-1)}{kN}+\frac{\eta}{kN}\\
&=&\frac{1}{2kN} G_1^{\mathbb Z}(\tilde u,\tilde v;(0,2kN))+\frac{\eta}{kN}\\
&\geq&\frac{1}{2kN} \inf\Bigl\{G_1^{\mathbb Z}(u,v;(0,2kN)): \\
&& \hspace{1cm} u(0)=v(0)=0, 
u(kN)=v(kN)=2kNz \Bigr\}+\frac{\eta}{ k N}, 
\end{eqnarray*}
and, by taking the 
limit as $k\to+\infty$, 
\begin{eqnarray*}
\displaystyle
\lambda_N z^2+\frac{\eta}{N}\geq g_{\rm hom}^{\mathbb Z}(z).
\end{eqnarray*}
Hence, since $g_{\rm hom}^{\mathbb Z}$ is convex, 
\begin{eqnarray*}
\Big(\inf_{N\in\mathbb N}\Big\{\displaystyle
\lambda_N z^2+\frac{\eta}{N}\Big\}\Big)^{\ast\ast}\geq g_{\rm hom}^{\mathbb Z}(z).
\end{eqnarray*}
Next we need to  prove  the opposite inequality. 
Let $u\in SBV(0,N)$ and $v\in H^1(0,N)$ be such that the boundary conditions 
$u(0)=v(0)=0$, $u(N)=v(N)=Nz$ 
hold and $S(u)\subset \mathbb N$. We denote the jump points of $u$ by $N_i$, $i=1,\dots k$, with 
$N_i<N_{i+1}$ for any $i=1,\dots, k-1$.  
Setting $N_0=0$ and $N_{k+1}=N$, we define 
$$n_i=N_i-N_{i-1} \quad \hbox{ and } \quad z_i=\frac{v(N_i)-v(N_{i-1})}{n_i}$$ 
for $i=1,\dots k+1$.
We then have 
$$\frac{1}{n_i}\tilde G_1(u,v; (N_{i-1}, N_{i}))\geq g(n_i,z_i)=
\lambda_{n_i}z_i^2$$ 
 for any $i$, so that 
\begin{eqnarray*}
\frac{1}{N}G_1^{\mathbb Z}(u,v; (0,N))&\geq&\sum_{i=1}^{k+1} 
\frac{n_i}{N} \lambda_{n_i}z_i^2 +
\frac{\eta k}{N}
\ = \ \sum_{i=1}^{k+1} 
\frac{n_i}{N} \big(\lambda_{n_i}z_i^2 +
\frac{\eta }{n_i}\big)\\
&\geq& \sum_{i=1}^{k+1} 
\frac{n_i}{N} \inf_{n\in\mathbb N}\Big\{
\lambda_{n}z_i^2 +
\frac{\eta }{n}\Big\}
\end{eqnarray*}
Since $\sum_{i=1}^{k+1}n_i=N$ and $\sum_{i=1}^{k+1}n_iz_i=Nz$, an application of Carath\'eodory's Theorem 
gives  
\begin{eqnarray*}
\frac{1}{N}G_1^{\mathbb Z}(u,v; (0,N))
&\geq& \Big( \inf_{n\in\mathbb N}\Big\{\lambda_{n}z^2 +
\frac{\eta }{n}\Big\}\Big)^{\ast\ast}.
\end{eqnarray*}
Taking the $\inf$ over the admissible functions and the limit for $N\to+\infty$ we get the inequality 
\begin{eqnarray*}
g_{\rm hom}^{\mathbb Z}(z)
&\geq& \Big( \inf_{n\in\mathbb N}\Big\{\lambda_{n}z^2 +
\frac{\eta }{n}\Big\}\Big)^{\ast\ast}
\end{eqnarray*}
concluding the proof.

